return items.map((item) => {
  const source = item.json || {};
  const payload = source.downstream_payload && typeof source.downstream_payload === 'object'
    ? source.downstream_payload
    : source;
  return { json: {
    ...payload,
    inbound_event_id: source.inbound_event_id || payload.inbound_event_id || null,
    processing_token: source.processing_token || payload.processing_token || null,
  } };
});

const row = items[0]?.json ?? {};
const parsedLeadId = Number(row.lead_id);
const leadId = Number.isSafeInteger(parsedLeadId) && parsedLeadId > 0 ? parsedLeadId : null;
const assigned = row.assignment_result === 'assigned' && Boolean(row.assigned_seller_id);
if (!leadId || !row.conversation_id || !row.phone_number) {
  return [{ json: { ...row, should_send_handoff: false, message: null, response_text: null, lead_id: null } }];
}
const message = assigned
  ? 'Gracias, ya registré tu solicitud y quedó asignada al equipo comercial. Una ejecutiva revisará los antecedentes para preparar una cotización acorde a tu proyecto.'
  : 'Gracias, ya registré tu solicitud. El equipo comercial podrá revisar el caso sin que tengas que repetir la información.';
return [{ json: {
  ...row,
  should_send_handoff: true,
  message,
  response_text: message,
  response_kind: assigned ? 'handoff_confirmed' : 'handoff_registered_unassigned',
  lead_id: leadId,
} }];

const row = items[0]?.json ?? {};

const OPERATIONAL_INTENTS = new Set([
  'complaint',
  'warranty_inquiry',
  'payment_proof',
  'invoice_request',
]);

const conversationId = Number(row.conversation_id);
const hasConversation = Number.isSafeInteger(conversationId) && conversationId > 0;
const phoneNumber = String(row.phone_number || '').trim();

const intent = String(row.intent || '').trim();
const isOperational = OPERATIONAL_INTENTS.has(intent);

const shouldWrite = hasConversation && Boolean(phoneNumber) && !isOperational;

const commercialBlocked = Array.isArray(row.commercial_missing_fields)
  && row.commercial_missing_fields.length > 0;

const qualified = Boolean(row.should_create_lead)
  && !commercialBlocked
  && row.confirmation_status === 'confirmed';

const requestedStatus = qualified ? 'qualified' : 'new';

return [
  {
    json: {
      ...row,
      opportunity_scope: {
        conversation_id: conversationId,
        phone_number: phoneNumber,
        source_number_id: Number(row.source_number_id) > 0 ? Number(row.source_number_id) : null,
        external_contact_id: row.external_contact_id || null,
        whatsapp_name: row.whatsapp_name || null,
        service: row.service || null,
        city: row.city || null,
        requirement: row.requirement || null,
        intent_code: intent || null,
        inbound_event_id: Number(row.inbound_event_id) > 0 ? Number(row.inbound_event_id) : null,
      },
      opportunity_write: shouldWrite,
      opportunity_status: requestedStatus,
      opportunity_skipped: !shouldWrite,
    },
  },
];

// =============================================================================
// Ensure Escalation Handoff — Unidad 3: escalamiento humano durable (P0).
// -----------------------------------------------------------------------------
// Nodo del dispatcher "WA - Inbound Downstream Dispatcher". SOURCE OF TRUTH
// del routing motivo->area->prioridad->responsable (PRD #22/#23/#9.5/#11) y
// del gate de no-cierre de intenciones operativas (PRD #22.16/#31.7).
//
// El mismo archivo es, en pruebas (harness), un modulo Node: expone
// HANDOFF_ROUTING, routeEscalation, evaluateClosureGate y buildIdempotencyKey
// para los tests de contrato. En n8n (Code node) solo se ejecuta la seccion
// final que lee `items`. Single source of truth: el fixture se reinyecta al
// workflow con tests/scripts/sync-workflow-nodes.mjs.
//
// Idempotency key: `{conversation_id}:{motivo}:{trigger}` — el trigger es el
// motivo textual normalizado (o 'intent:<codigo>'), de modo que un replay del
// mismo evento no duplica y un motivo distinto abre un handoff propio.
// =============================================================================

const HANDOFF_ROUTING = {
  talk_human: { area: 'sales', area_label: 'Ventas', prioridad: 'alta', responsable: 'Ejecutiva comercial' },
  frustration: { area: 'sales', area_label: 'Ventas', prioridad: 'alta', responsable: 'Ejecutiva comercial' },
  high_urgency: { area: 'sales', area_label: 'Ventas', prioridad: 'alta', responsable: 'Ejecutiva comercial' },
  large_project: { area: 'sales', area_label: 'Ventas', prioridad: 'alta', responsable: 'Ejecutiva comercial' },
  complex_installation: { area: 'sales', area_label: 'Ventas', prioridad: 'alta', responsable: 'Ejecutiva comercial' },
  stock_confirm: { area: 'sales', area_label: 'Ventas', prioridad: 'media', responsable: 'Ejecutiva comercial' },
  photos_eval: { area: 'sales', area_label: 'Ventas', prioridad: 'media', responsable: 'Ejecutiva comercial' },
  loop: { area: 'sales', area_label: 'Ventas', prioridad: 'media', responsable: 'Ejecutiva comercial' },
  b2b: { area: 'b2b', area_label: 'B2B', prioridad: 'alta', responsable: 'Patricia / Área B2B' },
  purchase_order: { area: 'b2b', area_label: 'B2B', prioridad: 'alta', responsable: 'Patricia / Área B2B' },
  payment_proof: { area: 'finance', area_label: 'Finanzas', prioridad: 'alta', responsable: 'Finanzas' },
  invoice: { area: 'finance', area_label: 'Finanzas', prioridad: 'media', responsable: 'Finanzas / Administración' },
  warranty: { area: 'post_sale', area_label: 'Postventa', prioridad: 'alta', responsable: 'Administración / Postventa' },
  post_sale: { area: 'post_sale', area_label: 'Postventa', prioridad: 'media', responsable: 'Administración / Postventa' },
  complaint: { area: 'claims', area_label: 'Reclamos', prioridad: 'urgente', responsable: 'Responsable de Reclamos' },
  scheduling_change: { area: 'scheduling', area_label: 'Programación', prioridad: 'media', responsable: 'Programación (despacho/instalación)' },
  committed_issue: { area: 'scheduling', area_label: 'Programación', prioridad: 'alta', responsable: 'Programación (despacho/instalación)' },
  discount: { area: 'management', area_label: 'Gerencia', prioridad: 'alta', responsable: 'Gerencia' },
  special_payment_condition: { area: 'management', area_label: 'Gerencia', prioridad: 'alta', responsable: 'Gerencia' },
};

// Fallback determinista por area declarada por la AI (contrato del advisor).
const AREA_FALLBACK = {
  sales: { area: 'sales', area_label: 'Ventas', prioridad: 'alta', responsable: 'Ejecutiva comercial' },
  b2b: { area: 'b2b', area_label: 'B2B', prioridad: 'alta', responsable: 'Patricia / Área B2B' },
  finance: { area: 'finance', area_label: 'Finanzas', prioridad: 'alta', responsable: 'Finanzas' },
  post_sale: { area: 'post_sale', area_label: 'Postventa', prioridad: 'media', responsable: 'Administración / Postventa' },
  claims: { area: 'claims', area_label: 'Reclamos', prioridad: 'urgente', responsable: 'Responsable de Reclamos' },
  scheduling: { area: 'scheduling', area_label: 'Programación', prioridad: 'media', responsable: 'Programación (despacho/instalación)' },
  management: { area: 'management', area_label: 'Gerencia', prioridad: 'alta', responsable: 'Gerencia' },
};

const DEFAULT_ROUTING = { area: 'sales', area_label: 'Ventas', prioridad: 'media', responsable: 'Ejecutiva comercial' };

const INTENT_TO_MOTIVE = {
  talk_to_human: 'talk_human',
  complaint: 'complaint',
  warranty_inquiry: 'warranty',
  payment_proof: 'payment_proof',
  invoice_request: 'invoice',
  b2b_request: 'b2b',
  purchase_order: 'purchase_order',
  discount_request: 'discount',
  reschedule_delivery: 'scheduling_change',
  reschedule_installation: 'scheduling_change',
  post_sale: 'post_sale',
  stock_inquiry: 'stock_confirm',
  returning_customer: 'loop',
  review: 'loop',
};

// Motivo por señales de texto del reason de escalamiento (PRD #22 triggers).
const REASON_TO_MOTIVE = [
  ['complaint', /reclamo|queja|molest|frustr|mala atencion|falla|roto|quebr|problema/i],
  ['warranty', /garant/i],
  ['payment_proof', /comprobante|transferencia|abono|pago|pago enviado/i],
  ['invoice', /factur/i],
  ['b2b', /b2b|empresa|constructora|inmobiliaria|licitacion|orden de compra|proveedor|volumen/i],
  ['discount', /descuento|igualar|bajo el precio|rebaja/i],
  ['special_payment_condition', /condicion (especial|servicio de pago|pago a 30)/i],
  ['large_project', /2\.000\.000|dos millones|millon/i],
  ['high_urgency', /urgent/i],
  ['scheduling_change', /reagend|cambio de fecha|fecha/i],
  ['committed_issue', /despacho|programada|programado|pedido comprometido/i],
  ['complex_installation', /instalacion|coordinacion logistica|acceso/i],
  ['stock_confirm', /stock|disponibilidad/i],
  ['photos_eval', /foto|fotos|imagen/i],
];

const normalizeReason = (value) => String(value ?? '').trim().replace(/\s+/g, ' ').toLowerCase();

const motiveFromReason = (reason) => {
  const text = normalizeReason(reason);
  if (!text) return null;
  for (const [motive, pattern] of REASON_TO_MOTIVE) {
    if (pattern.test(text)) return motive;
  }
  return null;
};

const routeEscalation = (row) => {
  const conversationId = Number(row.conversation_id);
  const hasConversation = Number.isSafeInteger(conversationId) && conversationId > 0;
  const phoneNumber = String(row.phone_number || '').trim();
  const shouldEscalate = Boolean(row.should_escalate) || Boolean(row.escalation_required);
  const area = String(row.escalation_area || '').trim();
  const aiRequestsOperational = Boolean(area && area !== 'none' && area !== 'sales');
  const escalated = shouldEscalate || aiRequestsOperational;

  if (!escalated || !hasConversation || !phoneNumber) {
return {
    escalated: false,
    write: false,
    motivo: null,
    routing: null,
    idempotency_key: null,
    trigger: null,
  };
  }

  const intent = String(row.intent || '').trim();
  const rawReason = String(row.escalation_reason || '').trim();
  const motivo = motiveFromReason(rawReason)
    || INTENT_TO_MOTIVE[intent]
    || (area && area !== 'none' ? area : null);
  const routing = HANDOFF_ROUTING[motivo] || AREA_FALLBACK[area] || DEFAULT_ROUTING;
  const trigger = rawReason || (intent ? `intent:${intent}` : routing.area);

  return {
    escalated: true,
    write: true,
    motivo: motivo || routing.area,
    routing,
    trigger,
    idempotency_key: buildIdempotencyKey(conversationId, motivo || routing.area, trigger),
  };
};

const buildIdempotencyKey = (conversationId, motivo, trigger) =>
  [conversationId, motivo, trigger].join(':');

// =============================================================================
// Gate de no-cierre (PRD #33.16, #33.8): ninguna intencion operativa
// (reclamo, garantia, comprobante, factura) ni B2B se cierra mientras el
// escalamiento no exista y este al menos 'notified'.
// =============================================================================
const OPERATIONAL_CLOSURE_INTENTS = new Set([
  'complaint',
  'warranty_inquiry',
  'payment_proof',
  'invoice_request',
  'b2b_request',
  'purchase_order',
]);

const NOTIFIED_OR_BETTER = new Set(['notified', 'acknowledged', 'resolved']);

const evaluateClosureGate = (input) => {
  const intent = String(input.intent || '').trim();
  const shouldEscalate = Boolean(input.should_escalate || input.escalation_required);
  const customerType = String(input.customer_type || '').trim();
  const leadClass = String(input.lead_class || '').trim();
  const operational = OPERATIONAL_CLOSURE_INTENTS.has(intent)
    || customerType === 'b2b'
    || leadClass === 'D';

  if (!operational || !shouldEscalate) {
    return {
      operational,
      requires_handoff: false,
      closure_allowed: true,
      required_status: null,
      reason: 'no_handoff_required',
      handoff_exists: false,
    };
  }

  const handoffExists = Boolean(input.handoff_exists);
  const handoffStatus = String(input.handoff_status || '').trim();
  if (!handoffExists) {
    return {
      operational,
      requires_handoff: true,
      closure_allowed: false,
      required_status: 'notified',
      reason: 'handoff_missing',
      handoff_exists: false,
    };
  }

  const ready = NOTIFIED_OR_BETTER.has(handoffStatus);
  return {
    operational,
    requires_handoff: true,
    closure_allowed: ready,
    required_status: 'notified',
    reason: ready ? 'handoff_notified' : 'handoff_pending',
    handoff_exists: true,
    handoff_status: handoffStatus,
  };
};

// =============================================================================
// Seccion n8n (Code node): procesa el item de entrada del dispatcher.
// En Node (harness) `items` no existe y este bloque no se ejecuta.
// =============================================================================
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    HANDOFF_ROUTING,
    AREA_FALLBACK,
    DEFAULT_ROUTING,
    motiveFromReason,
    routeEscalation,
    buildIdempotencyKey,
    evaluateClosureGate,
    OPERATIONAL_CLOSURE_INTENTS,
  };
}

if (typeof items !== 'undefined') {
  const row = items[0]?.json ?? {};
  const resolution = routeEscalation(row);
  const gate = evaluateClosureGate({
    intent: row.intent,
    should_escalate: resolution.escalated,
    customer_type: row.customer_type,
    lead_class: row.lead_class,
    handoff_exists: row.declared_handoff_exists === true && resolution.escalated,
    handoff_status: row.declared_handoff_status || row.handoff_status || 'pending',
  });

  return [
    {
      json: {
        ...row,
        handoff_write: resolution.write,
        handoff_skipped: !resolution.write,
        handoff_scope: {
          conversation_id: Number(row.conversation_id) > 0 ? Number(row.conversation_id) : null,
          phone_number: String(row.phone_number || '').trim() || null,
          source_number_id: Number(row.source_number_id) > 0 ? Number(row.source_number_id) : null,
          inbound_event_id: Number(row.inbound_event_id) > 0 ? Number(row.inbound_event_id) : null,
          motivo: resolution.motivo,
          area: resolution.routing?.area ?? null,
          area_label: resolution.routing?.area_label ?? null,
          prioridad: resolution.routing?.prioridad ?? null,
          responsable: resolution.routing?.responsable ?? null,
          idempotency_key: resolution.idempotency_key,
          trigger: resolution.trigger,
          escalation_reason: String(row.escalation_reason || '').trim() || null,
          escalation_area: String(row.escalation_area || '').trim() || null,
          intent: String(row.intent || '').trim() || null,
          estado: 'pending',
        },
        handoff_gate: gate,
      },
    },
  ];
}

// =============================================================================
// Prepare Handoff Notification — Unidad 3: notificacion durable al area.
// -----------------------------------------------------------------------------
// Nodo del dispatcher "WA - Inbound Downstream Dispatcher". Decide si el
// handoff debe notificarse en este turno y construye el payload del area.
//
// Reglas deterministas:
//   - Se notifica solo cuando el handoff existe y esta 'pending' con intentos
//     disponibles (notification_attempt_count < max_attempts).
//   - Un handoff ya 'notified'/'acknowledged'/'resolved' nunca se re-notifica
//     (verificable exactamente una vez: notified_at + audit).
//   - El reenvio por fallo lo disparan los reintentos del dispatch/recovery;
//     la idempotencia la garantiza el contador de intentos en la BD.
// =============================================================================

const NOTIFIED_OR_BETTER = new Set(['notified', 'acknowledged', 'resolved']);

const prepareHandoffNotification = (row) => {
  const handoffId = Number(row.handoff_id || row.declared_handoff_id || 0);
  const estado = String(row.handoff_estado || row.declared_handoff_status || 'pending').trim();
  const attempts = Number(row.handoff_attempts ?? row.notification_attempt_count ?? 0);
  const maxAttempts = Number(row.handoff_max_attempts ?? 3);
  const scope = row.handoff_scope || row.declared_handoff_scope || {};

  const exists = handoffId > 0 || Boolean(row.declared_handoff_exists);
  const alreadyNotified = NOTIFIED_OR_BETTER.has(estado);
  const attemptsLeft = attempts < maxAttempts;
  const shouldNotify = exists && !alreadyNotified && attemptsLeft && estado === 'pending';

  return {
    handoff_id: handoffId > 0 ? handoffId : null,
    handoff_estado: estado,
    notification_attempts: attempts,
    notification_max_attempts: maxAttempts,
    should_notify: shouldNotify,
    notification_skipped: !shouldNotify,
    notification_channel: 'internal',
    notification_payload: shouldNotify
      ? {
          channel: 'internal',
          idempotency_key: scope.idempotency_key || row.declared_handoff_key || null,
          motivo: scope.motivo || row.declared_handoff_motivo || null,
          area: scope.area || row.declared_handoff_area || null,
          area_label: scope.area_label || row.declared_handoff_area_label || null,
          prioridad: scope.prioridad || row.declared_handoff_prioridad || null,
          responsable: scope.responsable || row.declared_handoff_responsable || null,
          phone_number: scope.phone_number || row.phone_number || null,
          conversation_id: scope.conversation_id || row.conversation_id || null,
          escalation_reason: scope.escalation_reason || null,
        }
      : null,
  };
};

// =============================================================================
// Seccion n8n (Code node). En Node (harness) `items` no existe.
// =============================================================================
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { prepareHandoffNotification };
}

if (typeof items !== 'undefined') {
  const row = items[0]?.json ?? {};
  return [{ json: { ...row, ...prepareHandoffNotification(row) } }];
}

// =============================================================================
// Dispatch Handoff Notification — Unidad 3: stub determinista de notificacion.
// -----------------------------------------------------------------------------
// Nodo del dispatcher "WA - Inbound Downstream Dispatcher". Sustituye al
// canal real (ClickUp/WhatsApp interno) por un stub 100% determinista:
//   - por defecto emite outcome 'succeeded' (caso de produccion: el area
//     queda notificada una sola vez y el estado pasa a 'notified');
//   - los tests fuerzan fallos con row.notification_stub_mode='failed' para
//     validar reintentos (max 3) y auditoria sin tocar servicios externos.
//
// Nunca envia mensajes reales: el payload es un objeto interno que persiste
// `mark_handoff_attempt` con la idempotencia del handoff.
// =============================================================================

const dispatchHandoffNotification = (row) => {
  const shouldDispatch = Boolean(row.should_notify) && row.handoff_write !== false;
  const mode = String(row.notification_stub_mode || 'succeeded').trim();
  const outcome = mode === 'failed' ? 'failed' : 'succeeded';
  const statusCode = outcome === 'succeeded' ? 200 : 503;
  const error = outcome === 'failed'
    ? String(row.notification_stub_error || 'Stub notification failure (simulated)')
    : null;

  return {
    should_dispatch: shouldDispatch,
    dispatch_skipped: !shouldDispatch,
    notification_outcome: shouldDispatch ? outcome : 'skipped',
    notification_status_code: shouldDispatch ? statusCode : null,
    notification_error: shouldDispatch ? error : null,
    notification_stub: true,
  };
};

// =============================================================================
// Seccion n8n (Code node). En Node (harness) `items` no existe.
// =============================================================================
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { dispatchHandoffNotification };
}

if (typeof items !== 'undefined') {
  const row = items[0]?.json ?? {};
  return [{ json: { ...row, ...dispatchHandoffNotification(row) } }];
}

// =============================================================================
// Ensure Media Attachment — A-009: fotos y archivos recibidos (P0).
// -----------------------------------------------------------------------------
// Nodo del dispatcher "WA - Inbound Downstream Dispatcher". SOURCE OF TRUTH
// de la politica de media: tipos permitidos, limites de tamano, validacion de
// host (misma instancia Evolution) y gate de extension `attached_to`
// (ClickUp CR-014 PENDIENTE, no implementado).
//
// El mismo archivo es, en pruebas (harness), un modulo Node: expone
// MEDIA_POLICY, MEDIA_BACKOFF_SECONDS, evaluateMediaPolicy,
// buildMediaDedupeKey, sanitizeLog, shouldAllowMediaHost y mediaScopeFor para
// tests de contrato. En n8n (Code node "Ensure Media Attachment") solo se
// ejecuta la seccion final que lee `items`.
//
// Contrato:
//   - Sin media (attachment_type nulo) -> media_skipped=true, NO escribe.
//   - Con media -> media_write=true: SIEMPRE se registra metadata (trazabilidad
//     sin perder el evento), incluso si la descarga luego se rechaza.
//   - Politica evaluada ANTES de descargar: tipo no permitido, tamano fuera de
//     limite o url de host no permitido -> download_state 'rejected' con
//     rejected_reason (no se descarga).
//   - El rail JAMAS bloquea la respuesta al cliente (carril lateral).
//   - Idempotencia: dedupe key 'media:<media_key>'; fallback 'url:<external_url>'
//     (el hash se une despues de descargar).
// =============================================================================

const MEDIA_POLICY = {
  allowed_types: ['image', 'document', 'audio', 'video'],
  max_bytes: {
    image: 25 * 1024 * 1024,
    document: 25 * 1024 * 1024,
    audio: 25 * 1024 * 1024,
    video: 50 * 1024 * 1024,
  },
};

const MEDIA_BACKOFF_SECONDS = 10;

const normalizeSize = (value) => {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number') return Number.isSafeInteger(value) ? value : null;
  if (typeof value === 'bigint') return value <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(value) : null;
  if (typeof value === 'string' && /^\d+$/.test(value.trim())) {
    const parsed = Number(value.trim());
    return Number.isSafeInteger(parsed) ? parsed : null;
  }
  return null;
};

const evaluateMediaPolicy = (row, policyOverride) => {
  const policy = policyOverride || MEDIA_POLICY;
  const type = String(row.attachment_type || '').trim();
  if (!type) return { allowed_download: false, decision: 'skipped', reason: 'no_media' };
  if (!policy.allowed_types.includes(type)) {
    return { allowed_download: false, decision: 'rejected', reason: 'unsupported_type' };
  }
  const declaredSize = normalizeSize(row.file_size);
  if (declaredSize !== null && declaredSize > policy.max_bytes[type]) {
    return { allowed_download: false, decision: 'rejected', reason: 'oversized_declared' };
  }
  if (!String(row.external_url || '').trim()) {
    return { allowed_download: false, decision: 'rejected', reason: 'missing_url' };
  }
  return { allowed_download: true, decision: 'proceed', reason: null };
};

const buildMediaDedupeKey = (row) => {
  const mediaKey = String(row.media_key || '').trim();
  if (mediaKey) return `media:${mediaKey}`;
  const url = String(row.external_url || '').trim();
  if (url) return `url:${url}`;
  return null;
};

const sanitizeLog = (value) => {
  const text = String(value ?? '');
  if (text.length <= 96) return text;
  return `${text.slice(0, 92)}...(${text.length} chars)`;
};

const shouldAllowMediaHost = (url, allowedHosts) => {
  if (!url) return false;
  let parsed;
  try {
    parsed = new URL(url);
  } catch (_error) {
    return false;
  }
  const hosts = (allowedHosts || [])
    .map((host) => String(host).trim())
    .filter(Boolean);
  if (hosts.length === 0) return true;
  return hosts.includes(parsed.host) || hosts.includes(parsed.hostname);
};

const mediaScopeFor = (row, env = {}) => {
  const conversationId = Number(row.conversation_id);
  const inboundEventId = Number(row.inbound_event_id);
  const type = String(row.attachment_type || '').trim();

  const envMaxBytes = {};
  for (const mediaType of MEDIA_POLICY.allowed_types) {
    const envKey = `MEDIA_MAX_BYTES_${mediaType.toUpperCase()}`;
    const raw = env[envKey];
    if (raw !== undefined && raw !== null && raw !== '') {
      const parsed = Number(raw);
      if (Number.isFinite(parsed) && parsed > 0) envMaxBytes[mediaType] = parsed;
    }
  }
  const allowedHosts = String(env.MEDIA_ALLOWED_HOSTS || '')
    .split(',')
    .map((host) => host.trim())
    .filter(Boolean);

  const policy = {
    allowed_types: MEDIA_POLICY.allowed_types,
    max_bytes: { ...MEDIA_POLICY.max_bytes, ...envMaxBytes },
  };
  const evaluation = evaluateMediaPolicy(row, policy);
  const hostAllowed = shouldAllowMediaHost(String(row.external_url || '').trim(), allowedHosts);
  const rejectedByHost = evaluation.decision === 'proceed' && !hostAllowed;

  return {
    media_write: evaluation.decision !== 'skipped',
    media_skipped: evaluation.decision === 'skipped',
    media_scope: {
      media_key: String(row.media_key || '').trim() || null,
      external_url: String(row.external_url || '').trim() || null,
      media_url_log: sanitizeLog(row.external_url || ''),
      message_id: String(row.external_message_id || row.message_id || '').trim() || null,
      inbound_event_id: Number.isSafeInteger(inboundEventId) && inboundEventId > 0 ? inboundEventId : null,
      conversation_id: Number.isSafeInteger(conversationId) && conversationId > 0 ? conversationId : null,
      source_number_id: Number(row.source_number_id) > 0 ? Number(row.source_number_id) : null,
      instance_name: String(row.instance_name || '').trim() || null,
      phone_number: String(row.phone_number || '').trim() || null,
      attachment_type: type || null,
      mime_type: String(row.mime_type || '').trim() || null,
      filename: String(row.filename || '').trim() || null,
      file_size: normalizeSize(row.file_size),
      policy: {
        allowed_download: evaluation.allowed_download && hostAllowed,
        reason: rejectedByHost ? 'host_not_allowed' : evaluation.reason,
      },
      dedupe_key: buildMediaDedupeKey(row),
      url_host_allowed: hostAllowed,
      download_state: evaluation.decision === 'proceed'
        ? (hostAllowed ? 'pending' : 'rejected')
        : (evaluation.decision === 'skipped' ? 'pending' : 'rejected'),
      rejected_reason: rejectedByHost ? 'host_not_allowed' : evaluation.reason,
      attach_pending: false,
      attached_to: null,
    },
  };
};

// =============================================================================
// Seccion n8n (Code node): procesa el item de entrada del dispatcher.
// En Node (harness) `items` no existe y este bloque no se ejecuta.
// =============================================================================
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    MEDIA_POLICY,
    MEDIA_BACKOFF_SECONDS,
    normalizeSize,
    evaluateMediaPolicy,
    buildMediaDedupeKey,
    sanitizeLog,
    shouldAllowMediaHost,
    mediaScopeFor,
  };
}

if (typeof items !== 'undefined') {
  const row = items[0]?.json ?? {};
  const decision = mediaScopeFor(row, $env ?? {});
  const scope = decision.media_scope;
  return [{
    json: {
      ...row,
      ...scope,
      media_write: decision.media_write,
      media_skipped: decision.media_skipped,
      media_scope: scope,
    },
  }];
}

// =============================================================================
// Prepare Media Download — contrato de descarga determinista (A-009).
// -----------------------------------------------------------------------------
// Decide SI se descarga y CON QUE configuracion, a partir del estado
// persistido (download_state, retry_count, max_retries) y de la politica de
// media evaluada por "Ensure Media Attachment".
//
// Contrato:
//   - pending + intentos disponibles -> should_download=true con manifiesto.
//   - pending pero retry_count >= max_retries -> no descarga.
//   - estado terminal (downloaded/rejected/expired/exhausted) -> no descarga
//     (nunca se vuelve a bajar una media rechazada ni expirada).
//   - downloaded -> no descarga (el binario ya existe; idempotencia).
//
// El `download_manifest` expone la url COMPLETA solo como campo interno del
// rail (lo consume Dispatch en el mismo turno y el apply marca el intento).
// Para logging se usa el truncado `media_url_log`; ningun log de este carril
// emite la url completa.
// =============================================================================

const MEDIA_DEFAULT_MAX_BYTES = {
  image: 25 * 1024 * 1024,
  document: 25 * 1024 * 1024,
  audio: 25 * 1024 * 1024,
  video: 50 * 1024 * 1024,
};

const shouldDownload = (scope, row = {}) => {
  const state = String(row.media_download_state || scope.download_state || '').trim();
  const retryCount = Number(scope.retry_count ?? row.retry_count ?? 0) || 0;
  const maxRetries = Number(scope.max_retries ?? row.max_retries ?? 3) || 3;

  if (state === 'downloaded') return false;
  if (state === 'rejected') return false;
  if (state === 'expired') return false;
  if (state === 'exhausted') return false;
  if (retryCount >= maxRetries) return false;

  return true;
};

const buildDownloadManifest = (scope, row = {}, env = {}) => {
  const url = String(scope.external_url || row.external_url || '').trim();
  const mediaKey = String(scope.media_key || row.media_key || '').trim();
  const type = String(scope.attachment_type || row.attachment_type || '').trim();
  const mimeType = String(scope.mime_type || row.mime_type || '').trim();
  const envMax = Number(env[`MEDIA_MAX_BYTES_${type.toUpperCase()}`]);
  const maxBytes = Number.isFinite(envMax) && envMax > 0
    ? envMax
    : MEDIA_DEFAULT_MAX_BYTES[type] || 25 * 1024 * 1024;

  return {
    url,
    media_key: mediaKey || null,
    attachment_type: type,
    mime_type: mimeType,
    max_bytes: maxBytes,
    expected_sha256: String(row.sha256 || '') || null,
    dedupe_key: String(scope.dedupe_key || row.dedupe_key || '').trim() || null,
    storage_strategy: 'local_relative',
  };
};

// =============================================================================
// Seccion n8n (Code node): procesa el item de entrada del dispatcher.
// En Node (harness) `items` no existe y este bloque no se ejecuta.
// =============================================================================
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    shouldDownload,
    buildDownloadManifest,
  };
}

if (typeof items !== 'undefined') {
  const row = items[0]?.json ?? {};
  const scope = row.media_scope ?? {};
  const wantsDownload = shouldDownload(scope, row);
  return [{
    json: {
      ...row,
      should_download: wantsDownload,
      download_manifest: wantsDownload ? buildDownloadManifest(scope, row, $env ?? {}) : null,
    },
  }];
}

// =============================================================================
// Dispatch Media Download — descarga determinista (stub) + hash (A-009).
// -----------------------------------------------------------------------------
// Ejecuta la descarga a traves de `backend` (inyectable/mockeable, sin red) y
// calcula el SHA-256 real de los bytes recibidos.
//
// Contrato del backend (determinista para tests):
//   backend.fetch(manifest) -> { status: number, bytes?: Buffer|Uint8Array,
//                                 error?: string }
//
// Outcomes:
//   - 200 con bytes <= max_bytes        -> 'downloaded' (hash real de bytes).
//   - 200 con bytes > max_bytes        -> 'rejected' ('oversized_actual';
//                                          no se persiste el binario).
//   - 410/404 con 'expired'            -> 'expired' (url vencida; el mensaje
//                                          NO se pierde: message_id queda).
//   - 4xx/5xx/error                    -> 'failed' (reintento con backoff).
//
// Protecciones:
//   - La url debe pasar la allowlist del rail (policy.allowed_download); si
//     no, 'failed' con 'host_not_allowed' y el backend NO se toca.
//   - El hash se calcula SOLO sobre bytes en memoria; nunca se loguea ni
//     audita el binario; `storage_path` es relativo/interno (sin rutas
//     absolutas del sistema) y `storage_token` es un id generico.
// =============================================================================

const crypto = require('crypto');

const sha256Of = (buffer) => crypto.createHash('sha256').update(buffer).digest('hex');

const dispatchDownload = (manifest, backend, scope = {}) => {
  if (!manifest || !manifest.url) {
    return { outcome: 'failed', error: 'missing_url', attempt_spent: false };
  }
  if (scope.policy && scope.policy.allowed_download === false) {
    return { outcome: 'failed', error: scope.policy.reason || 'host_not_allowed', attempt_spent: false };
  }

  let response;
  try {
    response = backend.fetch(manifest);
  } catch (error) {
    return { outcome: 'failed', error: String(error?.message || 'backend_error'), attempt_spent: true };
  }

  const status = Number(response?.status) || 0;
  const error = String(response?.error || '').trim();

  if (status === 410 || (status >= 400 && error.includes('expired'))) {
    return { outcome: 'expired', error: error || 'media_expired', attempt_spent: true };
  }

  const raw = response?.bytes;
  const bytes = raw instanceof Uint8Array ? Buffer.from(raw) : raw;
  if (!Buffer.isBuffer(bytes)) {
    return { outcome: 'failed', error: error || 'no_bytes', attempt_spent: true };
  }

  if (bytes.length > manifest.max_bytes) {
    return {
      outcome: 'rejected',
      error: 'oversized_actual',
      reason: 'oversized_actual',
      bytes_length: bytes.length,
      max_bytes: manifest.max_bytes,
      attempt_spent: true,
    };
  }

  return {
    outcome: 'downloaded',
    sha256: sha256Of(bytes),
    bytes_length: bytes.length,
    storage_token: `m-${crypto.randomBytes(4).toString('hex')}`,
    storage_path: `media/${manifest.attachment_type || 'file'}/${crypto.randomBytes(4).toString('hex')}`,
    attempt_spent: true,
  };
};

// =============================================================================
// Seccion n8n (Code node): procesa el item de entrada del dispatcher.
// En Node (harness) `items` no existe y este bloque no se ejecuta.
// =============================================================================
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    sha256Of,
    dispatchDownload,
  };
}

if (typeof items !== 'undefined') {
  const row = items[0]?.json ?? {};
  const manifest = row.download_manifest ?? {};
  const backend = row.media_backend ?? { fetch: () => ({ status: 503, error: 'no_backend_configured' }) };
  const outcome = dispatchDownload(manifest, backend, row.media_scope ?? {});
  return [{
    json: {
      ...row,
      media_download: {
        outcome: outcome.outcome,
        sha256: outcome.sha256 ?? null,
        bytes_length: outcome.bytes_length ?? null,
        error: outcome.error ?? null,
        rejected_reason: outcome.reason ?? null,
        storage_token: outcome.storage_token ?? null,
        storage_path: outcome.storage_path ?? null,
        attempt_spent: Boolean(outcome.attempt_spent),
      },
    },
  }];
}
